+  // #13611
+  test('initSlots: should keep compiled slots whose name starts with _', () => {
+    const { slots } = renderWithSlots({
+      _foo: () => 'foo',
+      __bar: () => 'bar',
+      _: 1,
+      __: [1],
+    })
+    expect(Object.keys(slots)).toEqual(['_foo', '__bar'])
+    expect(slots._foo()).toBe('foo')
+    expect(slots.__bar()).toBe('bar')
+  })
+
+  test('updateSlots: should update and remove compiled slots whose name starts with _', async () => {
+    const show = ref(true)
+    let instance: any
+    const Child = () => {
+      instance = getCurrentInstance()
+      return 'child'
+    }
+    const Parent = {
+      render() {
+        return h(
+          Child,
+          null,
+          show.value
+            ? { _foo: () => 'foo', default: () => 'default', _: 2 }
+            : { default: () => 'default', _: 2 },
+        )
+      },
+    }
+    render(h(Parent), nodeOps.createElement('div'))
+    expect(Object.keys(instance.slots)).toEqual(['_foo', 'default'])
+
+    show.value = false
+    await nextTick()
+    expect(Object.keys(instance.slots)).toEqual(['default'])
+  })
+
